<?php
declare(strict_types=1);
/* Halaman bersama: Peta, Cek Wilayah, Informasi Kondisi, Peringatan, Tindakan, Riwayat, Sumber Data, Profil. */

function send_csv(string $name, array $rows): never {
    header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="' . $name . '"'); echo "\xEF\xBB\xBF"; $o = fopen('php://output', 'w'); foreach ($rows as $r) fputcsv($o, $r, ',', '"', '\\'); fclose($o); exit;
}
function sat_assets(): array { return ['head' => '', 'foot' => '<script src="assets/js/leaflet.js"></script><script src="assets/js/satmap.js"></script>']; }

/* ---------------- Peta zona kerawanan ---------------- */
function peta_sat_html(?int $sel, callable $color, string $layerQ): string {
    $pts = []; $polys = [];
    foreach (tbl('wilayah') as $w) {
        $col = $color($w); [$fill, $rank, $text] = $col; $sub = (string) ($col[3] ?? ''); $href = url('peta', ['base' => 'sat', 'sel' => $w['id_wilayah']] + ($layerQ !== 'tingkat' ? ['layer' => $layerQ] : []));
        if ($g = geo_real($w)) $polys[] = ['geo' => $g, 'fill' => $fill, 'rank' => $rank, 'text' => $text, 'nama' => $w['nama_wilayah'], 'href' => $href, 'sel' => $sel === $w['id_wilayah']];
        if ($t = wil_titik($w)) $pts[] = ['latlng' => $t, 'fill' => $fill, 'rank' => $rank, 'text' => $text, 'sub' => $sub, 'nama' => $w['nama_wilayah'], 'short' => short_name($w['nama_wilayah']), 'href' => $href, 'sel' => $sel === $w['id_wilayah']];
    }
    $data = ['sat' => 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', 'lab' => 'https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}', 'topo' => 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}', 'street' => 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', 'attr' => 'Tiles &copy; Esri &mdash; Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community', 'gmaps' => 'https://www.google.com/maps/place/Pulau+Panjang/@-5.9352676,106.1359652,5990m/data=!3m1!1e3', 'bounds' => [[-5.9451, 106.13876], [-5.91914, 106.16963]], 'polys' => $polys, 'points' => $pts];
    return '<div id="sat-map" class="leaf" role="application" aria-label="Peta satelit Pulo Panjang"></div><div class="sat-msg" id="sat-msg"></div><noscript>' . note_box('Peta satelit memerlukan JavaScript. Gunakan peta Skematik atau daftar kampung di bawah ini.', 'warn', 'alert') . '</noscript>'
        . '<script type="application/json" id="sat-data">' . json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP) . '</script>'
        . '<div class="sat-msg">' . note_box('<b>Titik kampung</b> memakai daftar koordinat tujuh kampung dari pengguna. <b>Garis pantai</b> adalah hasil digitasi perkiraan dari citra satelit (dapat meleset puluhan meter) dan <b>batas antar kampung</b> hanya perkiraan: pulau dibagi menurut titik kampung terdekat, bukan batas resmi.' . (user_role() === 'admin' ? ' Administrator dapat mengubah koordinat titik pada menu <b>Wilayah</b> atau mengganti batas dengan GeoJSON resmi.' : ''), '', 'info') . '</div>';
}
function pg_peta(): array {
    $role = user_role(); $adv = $role !== 'warga'; $base = gv('base') === 'sat' ? 'sat' : 'skema'; $layerQ = (string) gv('layer', 'tingkat'); $layerQ = ($adv && row('parameter', (int) $layerQ)) ? $layerQ : 'tingkat'; $sel = (int) gv('sel') ?: null; $w = $sel ? row('wilayah', $sel) : null; if (!$w) $sel = null;
    $color = $layerQ === 'tingkat' ? color_by_tingkat() : color_by_param((int) $layerQ); $keep = ['base' => $base] + ($layerQ !== 'tingkat' ? ['layer' => $layerQ] : []);
    $acts = seg([['skema', 'Skematik', 'map'], ['sat', 'Satelit Esri', 'mountain']], $base, fn($b) => url('peta', ['base' => $b] + ($sel ? ['sel' => $sel] : []) + ($layerQ !== 'tingkat' ? ['layer' => $layerQ] : [])), 'Jenis peta');

    $ts = tingkat_list(); $p = $layerQ !== 'tingkat' ? row('parameter', (int) $layerQ) : null;
    $legend = $p ? legend_param((int) $p['id_parameter']) : legend_tingkat();
    // tombol pilihan lapisan (tautan biasa: satu klik langsung mengganti peta, tanpa JavaScript)
    $layerBar = ''; $lyUrl = fn($l) => url('peta', ['base' => $base] + ($sel ? ['sel' => $sel] : []) + ($l !== 'tingkat' ? ['layer' => $l] : []));
    if ($adv) {   // panel lapisan sederhana: satu tombol utama + satu daftar pilihan data lain
        $opt = '<option value="tingkat"' . ($layerQ === 'tingkat' ? ' selected' : '') . '>Pilih data lain…</option>';
        foreach (uniq_list(array_column(tbl('parameter'), 'kelompok')) as $kel) { $opt .= '<optgroup label="' . e($kel) . '">'; foreach (tbl('parameter') as $pp) if ($pp['kelompok'] === $kel) $opt .= '<option value="' . $pp['id_parameter'] . '"' . ((string) $pp['id_parameter'] === $layerQ ? ' selected' : '') . '>' . e($pp['nama_parameter']) . '</option>'; $opt .= '</optgroup>'; }
        $ket = $p ? 'Warna peta menunjukkan <b>' . e(mb_strtolower($p['nama_parameter'])) . '</b> di tiap kampung.' : 'Warna peta menunjukkan <b>tingkat kerawanan banjir rob</b> tiap kampung.';
        $layerBar = '<form class="panel lys" method="get" action="index.php" aria-label="Lapisan peta"><input type="hidden" name="p" value="peta"><input type="hidden" name="base" value="' . e($base) . '">' . ($sel ? '<input type="hidden" name="sel" value="' . $sel . '">' : '')
            . '<span class="lys-l">' . ic('layers', 18) . 'Tampilkan di peta</span>'
            . '<a class="lys-main" href="' . e($lyUrl('tingkat')) . '" aria-pressed="' . ($layerQ === 'tingkat' ? 'true' : 'false') . '">' . ic('target', 16) . 'Tingkat kerawanan</a>'
            . '<span class="lys-or">atau</span><select class="select lys-sel" name="layer" aria-label="Pilih data lain" onchange="this.form.submit()"' . ($p ? ' data-on="1"' : '') . '>' . $opt . '</select><noscript><button class="btn btn-sm" type="submit">Tampilkan</button></noscript>'
            . '<p class="lys-k">' . $ket . '</p></form>'; }
    $dataPanel = '';
    if ($p) { $rows = []; foreach (tbl('wilayah') as $x) { $d = latest_data($x['id_wilayah'])[$p['id_parameter']] ?? null; $rows[] = ['w' => $x, 'd' => $d]; } usort($rows, fn($a, $b) => ($b['d']['skor'] ?? 0) <=> ($a['d']['skor'] ?? 0) ?: strcmp($a['w']['nama_wilayah'], $b['w']['nama_wilayah']));
        $dataPanel = '<div style="margin-top:16px"><div class="lbl" style="margin-bottom:8px">Nilai ' . e(mb_strtolower($p['nama_parameter'])) . ' per kampung <span class="faint">(skor tertinggi di atas)</span></div><div class="tbl-wrap"><table class="tbl" style="font-size:13.5px"><thead><tr><th>Kampung</th><th class="r">Nilai</th><th class="c">Skor</th><th>Sumber</th></tr></thead><tbody>';
        foreach ($rows as $r) { [$f, $rk] = $color($r['w']); $dataPanel .= '<tr><td><a href="' . e(url('peta', $keep + ['sel' => $r['w']['id_wilayah']])) . '" style="text-decoration:none;color:inherit;display:inline-flex;align-items:center;gap:8px"><span class="dot" style="--c:' . e($f) . ';width:11px;height:11px"></span><b>' . e($r['w']['nama_wilayah']) . '</b></a></td><td class="r num">' . ($r['d'] ? nfa($r['d']['nilai']) . ' ' . e($p['satuan']) : '–') . '</td><td class="c">' . ($r['d'] ? '<span class="tag plain">' . $r['d']['skor'] . '</span>' : '–') . '</td><td class="wrap muted" style="font-size:12.5px">' . ($r['d'] ? e(label_of('sumber_data', $r['d']['id_sumber'])) . ', ' . fmt_d($r['d']['tanggal_data']) : '–') . '</td></tr>'; }
        $dataPanel .= '</tbody></table></div><p class="faint" style="font-size:12.5px;margin-top:8px">Warna zona = skor kelas parameter ini (bukan tingkat kerawanan total). Angka di peta adalah nilai datanya. Nilai parameter pada prototipe ini masih contoh sampai data lapangan tersedia.</p></div>'; }
    $mapHtml = $base === 'sat' ? peta_sat_html($sel, $color, $layerQ) : map_html(['id' => 'pm', 'color' => $color, 'selected' => $sel, 'neutral' => true, 'href' => fn($x) => url('peta', $keep + ['sel' => $sel === $x['id_wilayah'] ? null : $x['id_wilayah']])]);
    $chips = ''; foreach (tbl('wilayah') as $x) { [$f, $rk] = $color($x); $on = $sel === $x['id_wilayah']; $chips .= '<a class="tag' . ($on ? '' : ' plain') . '"' . ($on ? ' style="--c:' . e($f) . '"' : '') . ' href="' . e(url('peta', $keep + ['sel' => $x['id_wilayah']])) . '" aria-pressed="' . ($on ? 'true' : 'false') . '">' . ($on ? lvl_icon($rk, 15) : '') . e($x['nama_wilayah']) . '</a>'; }
    $panel = $w ? ($adv ? wilayah_advanced($w) : wilayah_result($w, ['steps' => 3])) : '<div class="empty">' . ic('pin', 34) . '<b>Pilih wilayah</b><div>' . ($p ? 'Ketuk salah satu wilayah pada peta untuk melihat nilai ' . e(mb_strtolower($p['nama_parameter'])) . ' dan seluruh parameter penyusunnya.' : 'Ketuk salah satu wilayah pada peta untuk melihat tingkat kerawanan dan langkah yang perlu dilakukan.') . '</div></div>' . ($p ? '' : '<div class="hr"></div>' . implode('', array_map(fn($t) => '<div class="lvl-card" style="--c:' . e($t['warna']) . ';margin-bottom:8px">' . lvl_icon(rank_of($t['id_tingkat']), 20) . '<b>' . e($t['nama_tingkat']) . '</b><p>' . e($t['makna_warga']) . '</p></div>', $ts)));
    $h = page_head('Peta Zona Kerawanan', 'Zona kerawanan banjir rob di ' . e(lokasi_text()) . '. Koordinat ' . nf(-5.9269, 4) . '; ' . nf(106.1522, 4) . '. Pilih wilayah pada peta untuk melihat rinciannya.', $acts)
        . $layerBar . '<div class="grid g-side"><div class="panel">' . ($p ? '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px"><span class="tag" style="--c:var(--primary)">' . ic('layers', 15) . 'Lapisan aktif: ' . e($p['nama_parameter']) . ' (' . e($p['satuan']) . ')</span></div>' : '') . $mapHtml . '<div class="chips" role="group" aria-label="Daftar wilayah">' . $chips . '</div><div style="margin-top:14px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center">' . $legend . '<span class="faint" style="font-size:12.5px">Klik salah satu kampung; warna dan status ' . ($p ? 'skor parameter' : 'kerawanannya') . ' muncul setelah dipilih.</span></div>' . $dataPanel . '</div><div class="panel" id="peta-detail" style="align-self:start">' . $panel . '</div></div>';
    return ['title' => 'Peta Zona Kerawanan', 'html' => $h] + ($base === 'sat' ? ['foot' => sat_assets()['foot']] : []);
}

/* ---------------- Cek wilayah ---------------- */
function pg_cek_wilayah(): array {
    $q = trim((string) gv('q', '')); $ws = tbl('wilayah'); $sel = (int) gv('sel') ?: (my_wil_id() ?: ($ws[0]['id_wilayah'] ?? 0)); $w = row('wilayah', $sel);
    $list = array_values(array_filter($ws, fn($x) => $q === '' || mb_stripos($x['nama_wilayah'], $q) !== false)); $li = '';
    foreach ($list as $x) { $inf = info_wilayah($x['id_wilayah']); $on = $x['id_wilayah'] === $sel; $li .= '<a href="' . e(url('cek-wilayah', ['sel' => $x['id_wilayah']] + ($q !== '' ? ['q' => $q] : []))) . '#hasil" style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line);text-decoration:none;color:inherit;background:' . ($on ? 'var(--primary-soft)' : 'transparent') . ';' . ($on ? 'box-shadow:inset 4px 0 0 var(--primary)' : '') . '"><span><b style="display:block">' . e($x['nama_wilayah']) . '</b><span class="faint" style="font-size:13px">' . e($x['tipe']) . '</span></span>' . tingkat_tag($inf['tingkat'] ?? null) . '</a>'; }
    $h = page_head('Cek Wilayah', 'Cari wilayah tempat tinggal Anda untuk mengetahui tingkat kerawanan banjir rob dan langkah yang perlu dilakukan.')
        . '<div class="grid" style="grid-template-columns:minmax(0,340px) minmax(0,1fr);align-items:start"><div class="panel tight"><form class="tools" method="get" action="index.php"><input type="hidden" name="p" value="cek-wilayah"><label class="search" style="max-width:none"><span class="sr">Cari wilayah</span>' . ic('search', 18) . '<input class="input" type="search" name="q" placeholder="Cari nama wilayah" value="' . e($q) . '"></label></form>' . ($li ?: empty_state('Tidak ditemukan', 'Coba kata kunci lain.', 'search')) . '</div><div class="panel" id="hasil">' . ($w ? wilayah_result($w) : empty_state('Tidak ada wilayah', 'Belum ada wilayah terdaftar.', 'pin')) . '</div></div>';
    return ['title' => 'Cek Wilayah', 'html' => $h];
}

/* ---------------- Informasi kondisi ---------------- */
function pg_kondisi(): array {
    $tab = in_array(gv('tab'), ['laut', 'bmkg', 'param'], true) ? gv('tab') : 'laut'; $ser = array_key_exists((string) gv('ser'), OSEA_SER) ? (string) gv('ser') : 'pasut_m';
    if (user_role() === 'warga' && $tab === 'param') $tab = 'laut';
    $tabs = seg(array_values(array_filter([['laut', 'Pasang surut dan cuaca laut', 'waves'], ['bmkg', 'Cuaca BMKG', 'wind'], ['param', 'Parameter wilayah', 'mountain']], fn($x) => user_role() !== 'warga' || $x[0] !== 'param')), $tab, fn($t) => url('kondisi', ['tab' => $t]), 'Jenis informasi');
    if ($tab === 'laut') {
        $segs = seg(array_map(fn($k, $v) => [$k, $v[0]], array_keys(OSEA_SER), OSEA_SER), $ser, fn($k) => url('kondisi', ['tab' => 'laut', 'ser' => $k]), 'Variabel');
        $body = kondisi_strip() . '<div class="panel" style="margin-top:18px"><div class="panel-h"><div><h2>Grafik 72 jam</h2><p>24 jam terakhir (garis penuh) dan 48 jam ke depan (garis putus-putus).</p></div>' . $segs . '</div>' . osea_chart($ser, -24, 48) . '<div class="chart-leg"><span class="it"><i style="--c:' . OSEA_SER[$ser][2] . '"></i>Sebelum sekarang</span><span class="it"><i class="dash" style="--c:' . OSEA_SER[$ser][2] . '"></i>Prediksi</span></div></div>' . note_box('Data pasang surut, gelombang, dan arus pada prototipe ini adalah simulasi. Ambang batas yang memicu perubahan status peringatan ditetapkan administrator pada menu Peringatan.', '', 'info');
    } elseif ($tab === 'bmkg') {
        $body = '<div class="panel"><div class="panel-h"><div><h2>Prakiraan cuaca BMKG</h2><p>' . e(bmkg_cfg()['lokasi']) . '</p></div>' . bmkg_form('refresh', 'Perbarui', 'refresh') . '</div>' . bmkg_block('full') . '</div><div class="panel" style="margin-top:18px"><div class="panel-h"><h2>Peringatan dini cuaca BMKG</h2></div>' . bmkg_block('alerts') . '</div>';
    } else {
        $ws = tbl('wilayah'); $sel = (int) gv('w') ?: (my_wil_id() ?: ($ws[0]['id_wilayah'] ?? 0)); $c = $sel ? compute_skor($sel) : null;
        $pick = '<form method="get" action="index.php" style="display:flex;gap:8px;flex-wrap:wrap;min-width:260px"><input type="hidden" name="p" value="kondisi"><input type="hidden" name="tab" value="param"><select class="select" name="w" aria-label="Pilih wilayah" style="flex:1">' . implode('', array_map(fn($x) => '<option value="' . $x['id_wilayah'] . '"' . ($x['id_wilayah'] === $sel ? ' selected' : '') . '>' . e($x['nama_wilayah']) . '</option>', $ws)) . '</select><button class="btn" type="submit">Tampilkan</button></form>';
        $rows = ''; if ($c) foreach ($c['detail'] as $d) $rows .= '<tr><td>' . e($d['p']['kelompok']) . '</td><td><b>' . e($d['p']['nama_parameter']) . '</b></td><td class="r num">' . nfa($d['nilai']) . '</td><td>' . e($d['p']['satuan']) . '</td><td class="c">' . ($d['skor'] !== null ? '<span class="tag plain">' . $d['skor'] . '</span>' : '–') . '</td><td class="wrap">' . ($d['data'] ? e(label_of('sumber_data', $d['data']['id_sumber'])) : '–') . '</td><td>' . ($d['data'] ? fmt_d($d['data']['tanggal_data']) : '–') . '</td></tr>';
        $body = '<div class="panel tight"><div class="tools">' . $pick . '<span class="faint" style="font-size:13px">Nilai terbaru tiap parameter, lengkap dengan satuan, sumber, dan tanggal data.</span></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Kelompok</th><th>Parameter</th><th class="r">Nilai</th><th>Satuan</th><th class="c">Skor</th><th>Sumber</th><th>Tanggal data</th></tr></thead><tbody>' . ($rows ?: '<tr><td colspan="7">' . empty_state('Belum ada data', 'Wilayah ini belum memiliki data parameter.', 'db') . '</td></tr>') . '</tbody></table></div></div>';
    }
    return ['title' => 'Informasi Kondisi', 'head' => $tab === 'bmkg' ? bmkg_refresh_meta() : '', 'html' => page_head('Informasi Kondisi', 'Kondisi pasang surut, gelombang, angin, dan arus, serta parameter lingkungan yang dipakai menentukan kerawanan.', $tabs) . $body];
}

/* ---------------- Peringatan dini ---------------- */
function pg_peringatan(): array {
    if (user_role() === 'admin') return peringatan_admin();
    bmkg_ensure_fresh(); $act = active_warnings(); $all = tbl('peringatan'); usort($all, fn($a, $b) => strcmp($b['mulai'], $a['mulai'])); $ids = array_column($act, 'id_peringatan'); $arsip = array_values(array_filter($all, fn($p) => !in_array($p['id_peringatan'], $ids, true))); $share = user_role() === 'perangkat_desa'; $sp = status_peringatan(); if ($sp && ($sp['asal'] ?? '') !== 'manual') array_unshift($act, $sp);
    $h = page_head('Peringatan Dini', 'Informasi peringatan banjir rob yang sedang berlaku dan arsip peringatan sebelumnya.') . '<div class="stack"><div><h3 style="margin-bottom:12px;font-size:18px">Sedang berlaku</h3>' . ($act ? '<div class="stack">' . implode('', array_map(fn($p) => warn_card($p, $share), $act)) . '</div>' : '<div class="panel">' . empty_state('Tidak ada peringatan aktif', 'Saat ini tidak ada peringatan banjir rob yang berlaku. Tetap pantau informasi dari pihak berwenang.', 'checkc') . '</div>') . '</div>';
    $h .= '<div class="panel"><div class="panel-h"><div><h2>Dasar status desa saat ini</h2><p>Status dihitung otomatis dari prediksi pasang surut BIG, peringatan dini BMKG, dan laporan warga yang sudah diverifikasi.</p></div></div>' . status_rincian_html(false) . '</div><div class="panel"><div class="panel-h"><div><h2>Peringatan dini cuaca BMKG</h2><p>Peringatan resmi BMKG untuk wilayah Banten.</p></div></div>' . bmkg_block('alerts') . '</div><div><h3 style="margin-bottom:12px;font-size:18px">Arsip peringatan</h3>';
    if ($arsip) { $h .= '<div class="panel"><div class="list">'; foreach ($arsip as $p) $h .= '<div style="display:grid;grid-template-columns:auto 1fr;gap:6px 16px;align-items:start">' . status_tag($p['status']) . '<div><b>' . e($p['judul']) . '</b><div class="muted" style="font-size:13.5px">' . fmt_dt($p['mulai']) . ' sampai ' . fmt_dt($p['berakhir']) . ', ' . e(label_of('sumber_data', $p['id_sumber'])) . '</div><p style="margin-top:4px;font-size:14px;color:var(--ink-2)">' . e($p['isi']) . '</p></div></div>'; $h .= '</div></div>'; } else $h .= '<div class="panel">' . empty_state('Arsip kosong', 'Belum ada peringatan sebelumnya.', 'bell') . '</div>';
    return ['title' => 'Peringatan Dini', 'html' => $h . '</div></div>'];
}

/* ---------------- Tindakan / kesiapsiagaan ---------------- */
function chk_get(): array { $j = json_decode((string) ($_COOKIE['chk'] ?? ''), true); return is_array($j) ? array_map('intval', $j) : []; }
function pg_tindakan_post(): void {
    if (user_role() !== 'perangkat_desa') redirect(url('tindakan')); $lvl = (int) pv('lvl'); $ids = array_map('intval', (array) pv('done', []));
    $others = array_values(array_filter(chk_get(), fn($id) => ($t = row('tindakan', $id)) && $t['id_tingkat'] !== $lvl)); $mine = array_values(array_filter($ids, fn($id) => ($t = row('tindakan', $id)) && $t['id_tingkat'] === $lvl));
    setcookie('chk', json_encode(array_merge($others, $mine)), ['expires' => time() + 365 * 86400, 'path' => '/', 'samesite' => 'Lax']); flash('Daftar periksa disimpan di perangkat ini.'); redirect(url('tindakan', ['lvl' => $lvl]));
}
function pg_tindakan(): array {
    $ts = tingkat_list(); $role = user_role(); $my = my_wil_id(); $inf = $my ? info_wilayah($my) : null;
    $def = $role === 'perangkat_desa' ? end($ts)['id_tingkat'] : ($inf['tingkat']['id_tingkat'] ?? ($ts[1] ?? $ts[0])['id_tingkat']); $lvl = row('tingkat_kerawanan', (int) gv('lvl')) ? (int) gv('lvl') : $def; $t = row('tingkat_kerawanan', $lvl);
    $tabs = seg(array_map(fn($x, $i) => [(string) $x['id_tingkat'], $x['nama_tingkat']], $ts, array_keys($ts)), (string) $lvl, fn($v) => url('tindakan', ['lvl' => $v]), 'Tingkat');
    if ($role === 'perangkat_desa') {
        $list = tindakan_list($lvl); $ck = chk_get(); $done = count(array_filter($list, fn($x) => in_array($x['id_tindakan'], $ck, true)));
        $targets = array_values(array_filter(wil_rows(), fn($r) => $r['inf'] && $r['inf']['tingkat']['id_tingkat'] === $lvl));
        $h = page_head('Kesiapsiagaan dan Mitigasi', 'Daftar periksa tindakan per tingkat kerawanan untuk mendukung penyampaian informasi dan kesiapsiagaan di desa.', $tabs) . '<div class="grid g-main"><div class="panel"><div class="panel-h"><div><h2>Daftar periksa tindakan</h2><p>Centang tindakan yang sudah dikoordinasikan, lalu simpan. Centang tersimpan di perangkat ini.</p></div>' . tingkat_tag($t, true) . '</div><div style="display:flex;align-items:center;gap:12px;margin-bottom:16px"><div class="prog" style="flex:1;--c:' . e($t['warna']) . '"><i style="width:' . ($list ? round($done / count($list) * 100) : 0) . '%"></i></div><b class="num">' . $done . '/' . count($list) . '</b></div>';
        $h .= $list ? '<form method="post" action="' . e(url('tindakan', ['lvl' => $lvl])) . '">' . csrf_field() . '<input type="hidden" name="lvl" value="' . $lvl . '"><div class="list">' . implode('', array_map(fn($x) => '<label class="chk"><input type="checkbox" name="done[]" value="' . $x['id_tindakan'] . '"' . (in_array($x['id_tindakan'], $ck, true) ? ' checked' : '') . '><span>' . e($x['isi_tindakan']) . '</span></label>', $list)) . '</div><button class="btn btn-primary" style="margin-top:16px" type="submit">' . ic('check', 18) . 'Simpan daftar periksa</button></form>' : empty_state('Belum ada tindakan', 'Administrator belum menambahkan tindakan untuk tingkat ini.', 'shield');
        $h .= '</div><div class="stack"><div class="lvl-card" style="--c:' . e($t['warna']) . '">' . lvl_icon(rank_of($lvl), 22) . '<b>Makna bagi masyarakat</b><p>' . e($t['makna_warga']) . '</p></div><div class="panel"><div class="panel-h"><h2>Wilayah sasaran</h2></div>' . ($targets ? '<div class="list">' . implode('', array_map(fn($r) => '<div style="display:flex;justify-content:space-between;gap:10px"><span><b>' . e($r['w']['nama_wilayah']) . '</b><span class="faint" style="display:block;font-size:13px">' . e($r['w']['tipe']) . '</span></span><span class="num" style="text-align:right">' . nf($r['w']['jumlah_kk']) . ' KK<span class="faint" style="display:block;font-size:13px">skor ' . nf($r['inf']['skor'], 2) . '</span></span></div>', $targets)) . '</div>' : '<p class="muted">Tidak ada wilayah pada tingkat ini.</p>') . '</div></div></div>';
        return ['title' => 'Kesiapsiagaan dan Mitigasi', 'html' => $h];
    }
    $warn = status_peringatan();
    $h = page_head('Apa yang Harus Dilakukan?', 'Langkah kesiapsiagaan menghadapi banjir rob, disesuaikan dengan tingkat kerawanan wilayah.', $tabs) . ($inf ? note_box('Wilayah Anda, <b>' . e(label_of('wilayah', $my)) . '</b>, berada pada tingkat kerawanan <b>' . e($inf['tingkat']['nama_tingkat']) . '</b>.', '', 'pin') : note_box('Pilih wilayah pada menu Cek Wilayah agar Anda langsung melihat langkah yang sesuai.', '', 'pin'))
        . '<div class="grid g-main" style="margin-top:18px"><div class="panel"><div class="panel-h"><h2>Langkah yang perlu dilakukan</h2>' . tingkat_tag($t, true) . '</div>' . steps_html($lvl) . '</div><div class="stack"><div class="lvl-card" style="--c:' . e($t['warna']) . '">' . lvl_icon(rank_of($lvl), 22) . '<b>Artinya bagi masyarakat</b><p>' . e($t['makna_warga']) . '</p></div>' . ($warn ? '<div class="panel" style="border-left:6px solid ' . e(status_meta()[$warn['status']]['c']) . '"><div class="lbl">Peringatan yang berlaku</div><div style="margin:8px 0">' . status_tag($warn['status']) . '</div><b>' . e($warn['judul']) . '</b><p class="muted" style="font-size:14px;margin-top:4px">Berlaku sampai ' . fmt_dt($warn['berakhir']) . '.</p></div>' : '') . note_box('Ikuti selalu arahan perangkat desa dan pihak berwenang. Informasi ini bersifat pendukung kesiapsiagaan.', '', 'info') . '</div></div>';
    return ['title' => 'Apa yang Harus Dilakukan?', 'html' => $h];
}

/* ---------------- Riwayat banjir rob ---------------- */
function riwayat_columns(): array {
    return [['k' => 'tgl', 'l' => 'Tanggal', 'v' => fn($r) => $r['tanggal'], 'f' => fn($r) => '<b>' . fmt_d($r['tanggal']) . '</b>'], ['k' => 'w', 'l' => 'Wilayah', 'v' => fn($r) => label_of('wilayah', $r['id_wilayah']), 'f' => fn($r) => e(label_of('wilayah', $r['id_wilayah']))], ['k' => 't', 'l' => 'Tinggi genangan (cm)', 'v' => fn($r) => $r['tinggi_genangan_cm'], 'f' => fn($r) => cm_bar((float) $r['tinggi_genangan_cm'])], ['k' => 'd', 'l' => 'Durasi (jam)', 'cls' => 'r', 'v' => fn($r) => $r['durasi_jam'], 'f' => fn($r) => '<span class="num">' . nfa($r['durasi_jam']) . '</span>'], ['k' => 'p', 'l' => 'Penyebab', 'cls' => 'wrap', 'v' => fn($r) => $r['penyebab'], 'f' => fn($r) => e($r['penyebab'])], ['k' => 's', 'l' => 'Sumber', 'cls' => 'wrap', 'v' => fn($r) => label_of('sumber_data', $r['id_sumber']), 'f' => fn($r) => '<span class="muted">' . e(label_of('sumber_data', $r['id_sumber'])) . '</span>']];
}
function riwayat_cfg(): array {
    return ['id' => 'riw', 'table' => 'riwayat_rob', 'page' => 'riwayat', 'noun' => 'kejadian rob', 'add_label' => 'Tambah kejadian', 'columns' => riwayat_columns(), 'sort' => ['k' => 'tgl', 'dir' => -1], 'pageSize' => 8, 'search' => fn($r) => label_of('wilayah', $r['id_wilayah']) . ' ' . $r['penyebab'], 'search_ph' => 'Cari wilayah atau penyebab',
        'filters' => [['k' => 'w', 'l' => 'Wilayah', 'opts' => array_map(fn($w) => [$w['id_wilayah'], $w['nama_wilayah']], tbl('wilayah')), 'test' => fn($r, $v) => (string) $r['id_wilayah'] === $v]],
        'form' => ['id_wilayah', 'tanggal', 'tinggi_genangan_cm', 'durasi_jam', 'penyebab', 'id_sumber'], 'defaults' => fn() => ['tanggal' => date('Y-m-d'), 'id_sumber' => (function () { foreach (tbl('sumber_data') as $s) if (stripos($s['nama_sumber'], 'desa') !== false) return $s['id_sumber']; return tbl('sumber_data')[0]['id_sumber'] ?? null; })()]];
}
function pg_riwayat(): array {
    $admin = user_role() === 'admin'; $cfg = riwayat_cfg();
    if ($admin && ($x = crud_action($cfg)) !== null) return ['title' => 'Riwayat Banjir Rob', 'html' => $x];
    $rows = tbl('riwayat_rob'); $mx = pick_best($rows, fn($r) => $r['tinggi_genangan_cm']); $cnt = []; foreach ($rows as $r) $cnt[$r['id_wilayah']] = ($cnt[$r['id_wilayah']] ?? 0) + 1; arsort($cnt); $topId = array_key_first($cnt);
    $h = page_head('Riwayat Banjir Rob', $admin ? 'Catat kejadian rob sebagai informasi historis dan bahan validasi hasil analisis.' : 'Kejadian banjir rob sebelumnya sebagai informasi historis dan bahan validasi hasil analisis.') . '<div class="grid g4 keep2" style="margin-bottom:18px">' . stat_tile((string) count($rows), 'Kejadian tercatat') . stat_tile($mx ? nfa($mx['tinggi_genangan_cm']) : '–', 'Genangan tertinggi', $mx ? e(label_of('wilayah', $mx['id_wilayah'])) : '', 'var(--bad)', 'cm') . stat_tile($rows ? nf(sum(array_column($rows, 'durasi_jam')) / count($rows), 1) : '–', 'Rata-rata durasi', '', '#3B82C4', 'jam') . stat_tile($topId ? e(short_name(label_of('wilayah', $topId))) : '–', 'Paling sering terdampak', $topId ? $cnt[$topId] . ' kejadian' : '', 'var(--warn)') . '</div><div class="panel" style="margin-bottom:18px"><div class="panel-h"><div><h2>Kejadian per bulan</h2><p>Jumlah kejadian rob yang tercatat pada 14 bulan terakhir yang memiliki data.</p></div></div>' . month_bars($rows) . '</div>' . ($admin ? crud_list($cfg) : table_list($cfg));
    return ['title' => 'Riwayat Banjir Rob', 'html' => $h];
}

/* ---------------- Sumber data ---------------- */
function pg_sumber(): array {
    if (user_role() === 'admin') return sumber_admin();
    $cards = ''; foreach (tbl('sumber_data') as $s) { $id = $s['id_sumber']; $u = ['data parameter' => count(where('data_parameter', fn($x) => $x['id_sumber'] === $id)), 'data oseanografi' => count(where('data_oseanografi', fn($x) => $x['id_sumber'] === $id)), 'riwayat rob' => count(where('riwayat_rob', fn($x) => $x['id_sumber'] === $id)), 'peringatan' => count(where('peringatan', fn($x) => $x['id_sumber'] === $id))]; $parts = []; foreach ($u as $k => $n) if ($n) $parts[] = "$n $k";
        $cards .= '<article class="panel"><span class="tag plain" style="margin-bottom:12px">' . e($s['jenis']) . '</span><h3 style="font-size:17px;line-height:1.3;margin-bottom:10px">' . e($s['nama_sumber']) . '</h3>' . ($s['url'] ? '<a href="' . e($s['url']) . '" target="_blank" rel="noopener noreferrer" style="display:inline-flex;gap:6px;align-items:center;word-break:break-all;font-size:14px">' . ic('link', 16) . e(preg_replace('~^https?://~', '', $s['url'])) . '</a>' : '<span class="faint" style="font-size:14px">Tanpa tautan daring</span>') . '<div class="hr"></div><dl class="kv"><dt>Tanggal akses</dt><dd>' . fmt_d($s['tanggal_akses']) . '</dd><dt>Dipakai oleh</dt><dd>' . ($parts ? e(implode(', ', $parts)) : 'belum dipakai') . '</dd></dl></article>'; }
    return ['title' => 'Sumber Data', 'html' => page_head('Sumber Data', 'Asal setiap data dan informasi yang ditampilkan aplikasi. Setiap data memiliki sumber, tanggal, dan satuan yang dapat ditelusuri.') . note_box('Daftar sumber pada prototipe ini adalah contoh untuk keperluan pengembangan. Verifikasi dan lengkapi dengan sumber resmi sebelum data dipakai untuk keputusan nyata.', 'warn', 'alert') . '<div class="grid g3" style="margin-top:18px">' . $cards . '</div>'];
}

/* ---------------- Profil, akun, dan tampilan ---------------- */
function pg_profil_post(): void {
    $u = current_user(); $aksi = (string) pv('aksi');
    if ($aksi === 'nama') { $n = trim((string) pv('nama')); if ($n === '') flash('Nama tidak boleh kosong.', 'warn'); else { upd('pengguna', $u['id_pengguna'], ['nama' => mb_substr($n, 0, 100)]); flash('Nama disimpan.'); } }
    elseif ($aksi === 'sandi') { $o = (string) pv('lama'); $n = (string) pv('baru'); $n2 = (string) pv('baru2');
        if (!password_verify($o, $u['kata_sandi_hash'])) flash('Kata sandi saat ini tidak cocok.', 'warn'); elseif (mb_strlen($n) < 6) flash('Kata sandi baru minimal 6 karakter.', 'warn'); elseif ($n !== $n2) flash('Kata sandi baru dan pengulangannya tidak sama.', 'warn'); else { upd('pengguna', $u['id_pengguna'], ['kata_sandi_hash' => password_hash($n, PASSWORD_DEFAULT)]); session_regenerate_id(true); flash('Kata sandi diubah.'); } }
    elseif ($u['peran'] === 'admin' && $aksi === 'ekspor') { $out = []; foreach (array_keys(schema()) as $t) $out[$t] = tbl($t); header('Content-Type: application/json; charset=utf-8'); header('Content-Disposition: attachment; filename="basis-data-sea-warning-' . date('Ymd-His') . '.json"'); echo json_encode(['versi' => APP_VERSION, 'dibuat' => date('c'), 'tabel' => $out], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT); exit; }
    elseif ($u['peran'] === 'admin' && $aksi === 'reset') { if (pv('konfirmasi') !== 'RESET') flash('Ketik RESET untuk mengonfirmasi.', 'warn'); else { create_schema(true); seed_database(); do_logout(); session_start(); flash('Data contoh dipulihkan. Silakan masuk kembali.'); redirect(url('login')); } }
    redirect(url('profil'));
}
