    $h = page_head('Akun dan Tampilan', 'Kelola informasi akun, kata sandi, dan pilih tampilan yang paling nyaman dibaca.') . '<div class="grid g2" style="align-items:start"><div class="stack">';
    $h .= '<div class="panel"><div class="panel-h"><h2>Akun saya</h2></div><div style="display:flex;gap:14px;align-items:center;margin-bottom:18px"><span class="avatar" style="width:58px;height:58px;font-size:24px;background:' . ROLE_COLOR[$u['peran']] . ';color:#fff">' . e(mb_strtoupper(mb_substr($u['nama'], 0, 1))) . '</span><div><b style="font-size:18px;font-family:var(--font-display)">' . e($u['nama']) . '</b><div class="muted">@' . e($u['username']) . '</div><div style="margin-top:6px">' . role_tag($u['peran']) . '</div></div></div><form method="post" action="' . e(url('profil')) . '">' . csrf_field() . '<input type="hidden" name="aksi" value="nama"><div class="field"><label for="p-nama">Nama lengkap</label><input class="input" id="p-nama" name="nama" value="' . e($u['nama']) . '" maxlength="100"></div><button class="btn btn-primary" type="submit">' . ic('check', 18) . 'Simpan nama</button></form></div>';
    $h .= '<div class="panel"><div class="panel-h"><h2>Ubah kata sandi</h2></div><form method="post" action="' . e(url('profil')) . '">' . csrf_field() . '<input type="hidden" name="aksi" value="sandi"><div class="field"><label for="pw-old">Kata sandi saat ini</label><input class="input" id="pw-old" name="lama" type="password" autocomplete="current-password"></div><div class="row2"><div class="field"><label for="pw-new">Kata sandi baru</label><input class="input" id="pw-new" name="baru" type="password" autocomplete="new-password"></div><div class="field"><label for="pw-new2">Ulangi kata sandi baru</label><input class="input" id="pw-new2" name="baru2" type="password" autocomplete="new-password"></div></div><button class="btn btn-primary" type="submit">' . ic('lock', 18) . 'Ubah kata sandi</button></form></div></div><div class="stack">';
    $h .= '<div class="panel"><div class="panel-h"><div><h2>Tampilan</h2><p>Pilih skin yang nyaman. Pilihan tersimpan di peramban ini.</p></div></div><form method="post" action="index.php?p=skin" class="grid g2" style="gap:12px" role="radiogroup" aria-label="Pilih tampilan">' . csrf_field() . '<input type="hidden" name="back" value="' . e(url('profil')) . '">' . $skins . '</form></div>';
    if ($adm) $h .= '<div class="panel"><div class="panel-h"><div><h2>Basis data</h2><p>Data tersimpan di basis data ' . (db_driver() === 'mysql' ? 'MySQL/MariaDB' : 'SQLite') . ' pada server.</p></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><form method="post" action="' . e(url('profil')) . '" style="margin:0">' . csrf_field() . '<input type="hidden" name="aksi" value="ekspor"><button class="btn" type="submit">' . ic('download', 18) . 'Cadangkan (JSON)</button></form></div><div class="hr"></div><form method="post" action="' . e(url('profil')) . '"><div class="field"><label for="rst">Kembalikan data contoh (menghapus SEMUA data saat ini)</label><input class="input" id="rst" name="konfirmasi" placeholder="Ketik RESET untuk mengonfirmasi" autocomplete="off"></div>' . csrf_field() . '<input type="hidden" name="aksi" value="reset"><button class="btn btn-danger" type="submit">' . ic('refresh', 18) . 'Kembalikan data contoh</button></form></div>';
    $h .= '<div class="panel"><form method="post" action="index.php?p=logout">' . csrf_field() . '<button class="btn btn-danger btn-block" type="submit">' . ic('logout', 18) . 'Keluar dari akun</button></form></div></div></div>';
    return ['title' => 'Akun dan Tampilan', 'html' => $h];
}
function role_tag(string $r): string { return '<span class="tag" style="--c:' . (ROLE_COLOR[$r] ?? '#888') . '">' . ic(roles()[$r]['icon'] ?? 'user', 15) . e(roles()[$r]['label'] ?? $r) . '</span>'; }
